// TestimonialGrid.jsx (robust, ensures controls work)
import React, { useRef } from "react";

export default function TestimonialGrid({ videos = [] }) {
  const refs = useRef([]);

  function pauseAll(exceptIndex = -1) {
    refs.current.forEach((el, idx) => {
      if (!el) return;
      if (idx === exceptIndex) return;
      try { el.pause(); } catch(e) {}
    });
  }

  return (
    <div className="testimonials card">
      <h3>Testimonial Videos</h3>
      <div className="test-row">
        {videos.map((src, i) => (
          <div className="test-card" key={i}>
            <video
              ref={el => (refs.current[i] = el)}
              src={src}
              controls
              width="100%"
              height="160"
              crossOrigin="anonymous"
              onPlay={() => pauseAll(i)}
              onError={(e) => {
                console.error("Testimonial video load error:", e);
                // optionally show fallback UI
              }}
              style={{ borderRadius: 12, outline: "none" }}
            />
          </div>
        ))}
      </div>
    </div>
  );
}
